 bool CheckTransaction(const CTransaction& tx, TxValidationState& state)
@@ -46,9 +46,32 @@ bool CheckTransaction(const CTransaction& tx, TxValidationState& state)
     // of a tx as spent, it does not check if the tx has duplicate inputs.
     // Failure to run this check will result in either a crash or an inflation bug, depending on the implementation of
     // the underlying coins database.
-    std::set<COutPoint> vInOutPoints;
-    for (const auto& txin : tx.vin) {
-        if (!vInOutPoints.insert(txin.prevout).second)
+    //
+    // This runs for every transaction of every connected block, so it is on the initial block download
+    // critical path. Two strategies are used, both of which avoid the per-transaction node allocations of
+    // a std::set:
+    //
+    // * Small transactions (essentially all of them) are checked by comparing every pair of inputs. The
+    //   output index is compared first, which is cheap and rejects nearly all pairs without touching the
+    //   32-byte transaction id.
+    // * Large transactions fall back to sorting a contiguous buffer, which is O(n log n) instead of the
+    //   O(n^2) of the pairwise scan.
+    static constexpr size_t MAX_PAIRWISE_INPUTS{96};
+    if (tx.vin.size() <= MAX_PAIRWISE_INPUTS) {
+        for (size_t i{0}; i < tx.vin.size(); ++i) {
+            const COutPoint& prevout{tx.vin[i].prevout};
+            for (size_t j{0}; j < i; ++j) {
+                const COutPoint& other{tx.vin[j].prevout};
+                if (prevout.n == other.n && prevout.hash == other.hash)
+                    return state.Invalid(TxValidationResult::TX_CONSENSUS, "bad-txns-inputs-duplicate");
+            }
+        }
+    } else {
+        std::vector<COutPoint> sorted;
+        sorted.reserve(tx.vin.size());
+        for (const auto& txin : tx.vin) sorted.push_back(txin.prevout);
+        std::sort(sorted.begin(), sorted.end());
+        if (std::adjacent_find(sorted.begin(), sorted.end()) != sorted.end())
             return state.Invalid(TxValidationResult::TX_CONSENSUS, "bad-txns-inputs-duplicate");
     }

diff --git a/src/test/sigopcount_tests.cpp b/src/test/sigopcount_tests.cpp
index 5956ac5a65..58045bd64f 100644
--- a/src/test/sigopcount_tests.cpp
+++ b/src/test/sigopcount_tests.cpp
@@ -229,4 +229,153 @@ BOOST_AUTO_TEST_CASE(GetTxSigOpCost)
     }
 }

+/**
+ * GetTransactionSigOpCost() accumulates legacy, P2SH and witness sigops. P2SH and
+ * witness sigops both need the spent output of every input, and are computed in a
+ * single pass. This test uses transactions that mix P2SH, non-P2SH and witness inputs
+ * in several orders, so a mistake in which contribution is applied to which input
+ * (or in the flag gating) changes the total.
+ */
+BOOST_AUTO_TEST_CASE(GetTxSigOpCost_mixed_inputs)
+{
+    CKey key{GenerateRandomKey()};
+    const CPubKey pubkey{key.GetPubKey()};
+
+    // A P2SH output whose redeem script is a 2-of-2 multisig, so it contributes
+    // MAX_PUBKEYS_PER_MULTISIG sigops through GetSigOpCount(scriptSig).
+    const CScript redeem_script{CScript() << 1 << ToByteVector(pubkey) << ToByteVector(pubkey) << 2 << OP_CHECKMULTISIGVERIFY};
+    const CScript p2sh_spk{GetScriptForDestination(ScriptHash(redeem_script))};
+    const CScript p2sh_sig{CScript() << OP_0 << OP_0 << ToByteVector(redeem_script)};
+
+    // A plain P2PKH output: neither P2SH nor a witness program, so it contributes nothing
+    // to either count even though it is spent.
+    const CScript p2pkh_spk{GetScriptForDestination(PKHash(pubkey))};
+    const CScript p2pkh_sig{CScript() << OP_0 << OP_0};
+
+    // A P2WPKH output: contributes exactly one witness sigop.
+    const CScript p2wpkh_spk{GetScriptForDestination(WitnessV0KeyHash(pubkey))};
+    CScriptWitness witness;
+    witness.stack.emplace_back(0);
+    witness.stack.emplace_back(0);
+
+    enum class Kind { P2SH, P2PKH, P2WPKH };
+
+    // Expected contributions per input kind.
+    const auto expect{[&](std::span<const Kind> kinds, script_verify_flags flags) {
+        int64_t expected{0};
+        for (const Kind kind : kinds) {
+            switch (kind) {
+            case Kind::P2SH:
+                if (flags & SCRIPT_VERIFY_P2SH) expected += 2 * WITNESS_SCALE_FACTOR;
+                break;
+            case Kind::P2PKH:
+                break;
+            case Kind::P2WPKH:
+                if (flags & SCRIPT_VERIFY_WITNESS) expected += 1;
+                break;
+            }
+        }
+        return expected;
+    }};
+
+    const script_verify_flags all_flags{SCRIPT_VERIFY_P2SH | SCRIPT_VERIFY_WITNESS};
+
+    std::vector<std::vector<Kind>> orders{
+        {Kind::P2SH, Kind::P2PKH, Kind::P2WPKH},
+        {Kind::P2WPKH, Kind::P2PKH, Kind::P2SH},
+        {Kind::P2PKH, Kind::P2SH, Kind::P2WPKH},
+        {Kind::P2SH},
+        {Kind::P2WPKH},
+        {Kind::P2PKH},
+        {Kind::P2SH, Kind::P2SH},
+        {Kind::P2SH, Kind::P2WPKH, Kind::P2SH, Kind::P2WPKH},
+    };
+
+    for (const auto& kinds : orders) {
+        // Fresh coin view per order: outpoint hashes are derived from the outputs.
+        CCoinsViewCache coins{&CoinsViewEmpty::Get()};
+        CMutableTransaction spending;
+        spending.version = 1;
+
+        for (const Kind kind : kinds) {
+            CMutableTransaction creation;
+            creation.version = 1;
+            creation.vin = {CTxIn{COutPoint{}}};
+            CTxIn input;
+            switch (kind) {
+            case Kind::P2SH:
+                creation.vout = {CTxOut{1, p2sh_spk}};
+                input = CTxIn{COutPoint{}, p2sh_sig};
+                break;
+            case Kind::P2PKH:
+                creation.vout = {CTxOut{1, p2pkh_spk}};
+                input = CTxIn{COutPoint{}, p2pkh_sig};
+                break;
+            case Kind::P2WPKH:
+                creation.vout = {CTxOut{1, p2wpkh_spk}};
+                input = CTxIn{COutPoint{}, CScript{}};
+                input.scriptWitness = witness;
+                break;
+            }
+            const CTransaction creation_tx{creation};
+            // Distinguish the outpoints of identical outputs in the same order.
+            input.prevout = COutPoint{creation_tx.GetHash(), 0};
+            spending.vin.push_back(input);
+            AddCoins(coins, creation_tx, 0);
+        }
+        spending.vout = {CTxOut{1, CScript{}}};
+
+        const CTransaction spending_tx{spending};
+        BOOST_CHECK_EQUAL(GetTransactionSigOpCost(spending_tx, coins, all_flags), expect(kinds, all_flags));
+        // Note: WITNESS without P2SH is not a valid combination for this function
+        // (CountWitnessSigOps asserts P2SH is set whenever WITNESS is).
+        BOOST_CHECK_EQUAL(GetTransactionSigOpCost(spending_tx, coins, SCRIPT_VERIFY_P2SH), expect(kinds, SCRIPT_VERIFY_P2SH));
+        BOOST_CHECK_EQUAL(GetTransactionSigOpCost(spending_tx, coins, /*flags=*/0), 0);
+    }
+}
+
+/**
+ * The legacy sigop count covers every scriptSig and scriptPubKey of the transaction and
+ * is independent of the flags; the witness contribution is added per input. This pins the
+ * relative weighting so a merge of the two passes cannot silently double-count.
+ */
+BOOST_AUTO_TEST_CASE(GetTxSigOpCost_legacy_and_witness_weighting)
+{
+    // Two multisig outputs: plain legacy sigops in the scriptPubKeys.
+    CMutableTransaction mtx;
+    mtx.version = 1;
+    mtx.vin = {CTxIn{COutPoint{Txid::FromUint256(uint256::ONE), 0}, CScript{}, CTxIn::SEQUENCE_FINAL}};
+    const CScript multisig{CScript() << 1 << std::vector<unsigned char>(33, 0x02) << std::vector<unsigned char>(33, 0x03) << 2 << OP_CHECKMULTISIG};
+    mtx.vout = {CTxOut{1, multisig}, CTxOut{1, multisig}};
+
+    CCoinsViewCache coins{&CoinsViewEmpty::Get()};
+
+    // The prevout is not P2SH and not a witness program, so it adds nothing to either
+    // the P2SH or the witness count. The cost must be exactly the legacy count scaled by
+    // WITNESS_SCALE_FACTOR.
+    CMutableTransaction creation;
+    creation.version = 1;
+    creation.vin = {CTxIn{COutPoint{}}};
+    creation.vout = {CTxOut{1, CScript() << OP_TRUE}};
+    const CTransaction creation_tx{creation};
+    AddCoins(coins, creation_tx, 0);
+    mtx.vin[0].prevout = COutPoint{creation_tx.GetHash(), 0};
+
+    const CTransaction tx{mtx};
+    const int64_t legacy{static_cast<int64_t>(GetLegacySigOpCount(tx)) * WITNESS_SCALE_FACTOR};
+    BOOST_CHECK_GT(legacy, 0);
+
+    BOOST_CHECK_EQUAL(GetTransactionSigOpCost(tx, coins, SCRIPT_VERIFY_P2SH | SCRIPT_VERIFY_WITNESS), legacy);
+    BOOST_CHECK_EQUAL(GetTransactionSigOpCost(tx, coins, /*flags=*/0), legacy);
+
+    // Coinbase transactions short-circuit after the legacy count, without touching the
+    // coins view (an empty view would otherwise trip the !coin.IsSpent() assertion).
+    CMutableTransaction coinbase{mtx};
+    coinbase.vin[0].prevout.SetNull();
+    const CCoinsViewCache empty_coins{&CoinsViewEmpty::Get()};
+    BOOST_CHECK_EQUAL(GetTransactionSigOpCost(CTransaction{coinbase}, empty_coins,
+                                              SCRIPT_VERIFY_P2SH | SCRIPT_VERIFY_WITNESS),
+                      legacy);
+}
+
 BOOST_AUTO_TEST_SUITE_END()
diff --git a/src/test/transaction_tests.cpp b/src/test/transaction_tests.cpp
index a0d222e303..2e1c4ddd99 100644
--- a/src/test/transaction_tests.cpp
+++ b/src/test/transaction_tests.cpp
@@ -38,6 +38,8 @@

 #include <functional>
 #include <map>
+#include <memory>
+#include <optional>
 #include <string>
 #include <vector>

@@ -1242,6 +1244,178 @@ BOOST_AUTO_TEST_CASE(calculatesequencelocks_tx_version_test)
     check_min_height(/*version=*/std::numeric_limits<uint32_t>::max(), /*expected_min_height=*/coin_height);
 }

+/**
+ * EvaluateSequenceLocks() compares the lock pair against the block height and the
+ * median time past of the previous block. Only a time-based (non-negative) entry in
+ * lockPair.second may cause the median-time-past comparison; the {-1, -1} pair that
+ * CalculateSequenceLocks() returns when no relative lock applies must always pass.
+ *
+ * These tests pin the exact boundaries, since the fast path in EvaluateSequenceLocks()
+ * relies on all three of: block times are non-negative, -1 sorts below every real time,
+ * and the height comparison is strict.
+ */
+BOOST_AUTO_TEST_CASE(evaluatesequencelocks_boundaries)
+{
+    // Previous block supplies the median time past. GetMedianTimePast() of a single
+    // element is that element's time, so this is exactly @prev_time.
+    constexpr int64_t prev_time{1'600'000'000};
+    CBlockIndex prev{};
+    prev.nHeight = 99;
+    prev.nTime = static_cast<uint32_t>(prev_time);
+
+    CBlockIndex block{};
+    block.pprev = &prev;
+    block.nHeight = 100;
+
+    const auto evaluate{[&](int min_height, int64_t min_time) {
+        return EvaluateSequenceLocks(block, {min_height, min_time});
+    }};
+
+    // The "no relative lock" pair always passes, and must not read the median time past.
+    BOOST_CHECK(evaluate(-1, -1));
+
+    // Height comparison is strict: nMinHeight >= block height fails, one below passes.
+    BOOST_CHECK(!evaluate(/*min_height=*/100, /*min_time=*/-1));
+    BOOST_CHECK(evaluate(/*min_height=*/99, /*min_time=*/-1));
+    BOOST_CHECK(!evaluate(/*min_height=*/101, /*min_time=*/-1));
+
+    // Time comparison is strict against the previous block's median time past.
+    BOOST_CHECK(!evaluate(/*min_height=*/-1, /*min_time=*/prev_time));
+    BOOST_CHECK(evaluate(/*min_height=*/-1, /*min_time=*/prev_time - 1));
+
+    // A failing height must be reported even when the time would pass, and vice versa.
+    BOOST_CHECK(!evaluate(/*min_height=*/100, /*min_time=*/prev_time - 1));
+    BOOST_CHECK(!evaluate(/*min_height=*/99, /*min_time=*/prev_time));
+
+    // max int64 is the saturating value used for effectively unlimited relative locks.
+    BOOST_CHECK(!evaluate(/*min_height=*/std::numeric_limits<int>::max(), /*min_time=*/-1));
+    BOOST_CHECK(!evaluate(/*min_height=*/-1, /*min_time=*/std::numeric_limits<int64_t>::max()));
+
+    // Genesis-like case: a median time past of 0 must still reject a lock time of 0,
+    // because the comparison is >=, not >.
+    CBlockIndex prev_zero{};
+    prev_zero.nHeight = 0;
+    prev_zero.nTime = 0;
+    CBlockIndex block_one{};
+    block_one.pprev = &prev_zero;
+    block_one.nHeight = 1;
+    BOOST_CHECK(!EvaluateSequenceLocks(block_one, {-1, 0}));
+    BOOST_CHECK(EvaluateSequenceLocks(block_one, {-1, -1}));
+}
+
+/**
+ * ConnectBlock() skips the per-input coin lookups that fill prevheights when no height
+ * can possibly be read: when BIP68 is not enforced for the block, when the tx version is
+ * below 2, or when no input has an active relative lock.
+ *
+ * This pins the invariant that makes that safe: in exactly those cases the result of
+ * SequenceLocks() is independent of the input heights. It also checks the converse, so the
+ * test would fail if the skip condition were widened to a case where heights do matter.
+ */
+BOOST_AUTO_TEST_CASE(sequencelocks_heights_only_matter_when_bip68_applies)
+{
+    // Build a small chain so that GetMedianTimePast() and GetAncestor() work for the
+    // time-based branch: 11 entries are needed for a non-trivial median.
+    constexpr int64_t base_time{1'600'000'000};
+    std::vector<std::unique_ptr<CBlockIndex>> chain;
+    for (int h{0}; h < 120; ++h) {
+        chain.push_back(std::make_unique<CBlockIndex>());
+        chain.back()->nHeight = h;
+        chain.back()->nTime = static_cast<uint32_t>(base_time + h * 600);
+        chain.back()->pprev = h == 0 ? nullptr : chain[h - 1].get();
+    }
+    const CBlockIndex& block{*chain.back()};
+
+    // One input with the given sequence, and the given number of inputs.
+    const auto make_tx{[&](uint32_t version, std::vector<uint32_t> sequences) {
+        CMutableTransaction mtx;
+        mtx.version = version;
+        for (const uint32_t seq : sequences) {
+            mtx.vin.emplace_back(COutPoint{}, CScript{}, seq);
+        }
+        mtx.vout.emplace_back(1, CScript{} << OP_TRUE);
+        return CTransaction{mtx};
+    }};
+
+    // The condition under which ConnectBlock() fills in prevheights.
+    const auto heights_needed{[](int flags, const CTransaction& tx) {
+        if (!(flags & LOCKTIME_VERIFY_SEQUENCE)) return false;
+        if (tx.version < 2) return false;
